#requires -Version 5.1
[CmdletBinding()]
param(
    [ValidateSet('Deploy', 'Build', 'Check', 'Inspect', 'Desktop', 'Tools', 'Bootstrap')]
    [string]$Mode = 'Deploy',
    [string]$SourceName,
    [switch]$Repair
)

$ErrorActionPreference = 'Stop'

# Prepare a ZIP supplied beside the project, without overwriting Git-managed launchers.
if ($MyInvocation.InvocationName -ne '.' -and $Mode -ne 'Desktop' -and (Test-Path -LiteralPath (Join-Path $PSScriptRoot 'offline-delivery'))) {
    try {
        if ($Mode -eq 'Build') { throw 'Offline deliveries are prebuilt. Use Deploy or Check.' }
        $prepare = Join-Path $PSScriptRoot 'deepseek_harness_desktop\scripts\offline\prepare-offline.ps1'
        if (-not (Test-Path -LiteralPath $prepare)) { throw 'Offline preparation script missing. Pull the latest Git source first.' }
        & $prepare -Root $PSScriptRoot -ReadOnly:($Mode -in @('Check', 'Inspect'))
    } catch { Write-Host ('Offline package preparation failed: ' + $_.Exception.Message) -ForegroundColor Red; exit 1 }
}
# A distributed offline payload takes precedence; never fall back to network installation.
$offlineInstaller = Join-Path $PSScriptRoot 'offline\install.ps1'
if ((Test-Path -LiteralPath $offlineInstaller) -and $MyInvocation.InvocationName -ne '.') {
    $sourceInstaller = Join-Path $PSScriptRoot 'deepseek_harness_desktop\scripts\offline\install.ps1'
    if (Test-Path -LiteralPath $sourceInstaller) {
        & $sourceInstaller -Mode $Mode -Repair:$Repair -WorkbenchRoot $PSScriptRoot -PackageDirectory (Join-Path $PSScriptRoot 'offline') -PreserveLaunchers
    } else { & $offlineInstaller -Mode $Mode -Repair:$Repair }
    $offlineResult = $LASTEXITCODE
    if ($offlineResult -ne 0) { exit $offlineResult }
    if ($Mode -in @('Deploy', 'Tools', 'Bootstrap')) {
        $settingsScript = Join-Path $PSScriptRoot 'deepseek_harness_desktop\scripts\settings-sync.cjs'
        if ((Test-Path -LiteralPath $settingsScript) -and (Test-Path -LiteralPath (Join-Path $PSScriptRoot 'shared-settings\manifest.json'))) {
            & (Join-Path $PSScriptRoot 'runtime-node\node.exe') $settingsScript apply $PSScriptRoot
            if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
        }
    }
    exit 0
}
$ErrorActionPreference = 'Stop'
$script:Root = $PSScriptRoot
$script:Step = 'preflight'
$script:Log = $null
$script:BackupRoot = $null
$script:Utf8 = New-Object System.Text.UTF8Encoding($false)
$script:Versions = @{ Node = '24.13.1'; Dsh = '0.1.5-rc.1'; Pnpm = '11.24.0'; Electron = '44.1.1'; Web = '0.3.23' }
$script:ChatName = '@linxin666/dsh-client-ui-plain-chat'

function Read-Json([string]$Path) {
    Get-Content -LiteralPath $Path -Raw -Encoding UTF8 | ConvertFrom-Json
}
function Set-Field($Object, [string]$Name, $Value) {
    $Object | Add-Member -NotePropertyName $Name -NotePropertyValue $Value -Force
}
function Ensure-Object($Object, [string]$Name) {
    if ($null -eq $Object.$Name) { Set-Field $Object $Name ([pscustomobject]@{}) }
    return $Object.$Name
}
function Write-Log([string]$Message) {
    $line = '[{0}] [{1}] {2}' -f (Get-Date -Format 'HH:mm:ss'), $script:Step, $Message
    Write-Host $line
    if ($script:Log) { [IO.File]::AppendAllText($script:Log, $line + [Environment]::NewLine, $script:Utf8) }
}
function New-Directory([string]$Path) { [IO.Directory]::CreateDirectory($Path) | Out-Null }
function Require-File([string]$Path) {
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { throw "Required file missing: $Path" }
}
function Backup-File([string]$Path) {
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return }
    if (-not $script:BackupRoot) { throw 'Backup destination is not initialized.' }
    $Path = [IO.Path]::GetFullPath($Path)
    if (-not $Path.StartsWith($script:Root.TrimEnd('\') + '\', [StringComparison]::OrdinalIgnoreCase)) { throw 'Backup input must stay inside the workbench.' }
    $relative = $Path.Substring($script:Root.TrimEnd('\').Length).TrimStart('\')
    $target = Join-Path $script:BackupRoot $relative
    if (-not (Test-Path -LiteralPath $target)) {
        New-Directory (Split-Path -Parent $target)
        Copy-Item -LiteralPath $Path -Destination $target
    }
}
function Write-Text([string]$Path, [string]$Content, [switch]$Bom) {
    if ((Test-Path -LiteralPath $Path) -and ([IO.File]::ReadAllText($Path) -eq $Content)) { return }
    Backup-File $Path
    New-Directory (Split-Path -Parent $Path)
    $encoding = $script:Utf8
    if ($Bom) { $encoding = New-Object System.Text.UTF8Encoding($true) }
    $temporary = $Path + '.deploy-' + [guid]::NewGuid().ToString('N') + '.tmp'
    [IO.File]::WriteAllText($temporary, $Content, $encoding)
    Move-Item -LiteralPath $temporary -Destination $Path -Force
}
function Write-Json([string]$Path, $Value) { Write-Text $Path (($Value | ConvertTo-Json -Depth 100) + "`n") }
function Invoke-Tool([string]$Exe, [string[]]$Arguments, [string]$Directory = $script:Root) {
    Push-Location -LiteralPath $Directory
    try {
        # Native stderr is diagnostic output, not a PowerShell exception. Exit status decides success.
        $savedPreference = $ErrorActionPreference
        $ErrorActionPreference = 'Continue'
        & $Exe @Arguments 2>&1 | ForEach-Object {
            $message = [string]$_
            if ($_ -is [Management.Automation.ErrorRecord]) { $message = $_.Exception.Message }
            if ($message -ne 'System.Management.Automation.RemoteException') { Write-Log $message }
        }
        $code = $LASTEXITCODE
        $ErrorActionPreference = $savedPreference
        if ($code -ne 0) { throw "Command failed (exit $code): $Exe; step: $script:Step" }
    } finally { $ErrorActionPreference = $savedPreference; Pop-Location }
}
function Get-SourceCandidates {
    foreach ($directory in Get-ChildItem -LiteralPath $script:Root -Directory) {
        $manifest = Join-Path $directory.FullName 'package.json'
        if (-not (Test-Path -LiteralPath $manifest)) { continue }
        try { $package = Read-Json $manifest } catch { continue }
        if ($package.name -eq 'dsh-web' -and (Test-Path -LiteralPath (Join-Path $directory.FullName 'desktop\src\main.cjs'))) {
            $directory
        }
    }
}
function Select-Source {
    $candidates = @(Get-SourceCandidates)
    if ($SourceName) {
        $selected = @($candidates | Where-Object Name -CEQ $SourceName)
        if ($selected.Count -ne 1) { throw 'SourceName must name one detected immediate child directory.' }
        return $selected[0].FullName
    }
    if ($candidates.Count -eq 0) { throw 'No complete dsh-web source found. Put deploy.ps1 beside the modified source directory, not inside it.' }
    if ($candidates.Count -eq 1) { return $candidates[0].FullName }
    # Reuse an explicit previous selection only for launching/checking/building. Deployment asks again.
    $selectionFile = Join-Path $script:Root 'runtime-dev\deployment-selection.json'
    if ($Mode -ne 'Deploy' -and (Test-Path -LiteralPath $selectionFile)) {
        $saved = (Read-Json $selectionFile).sourceName
        $match = @($candidates | Where-Object Name -CEQ $saved)
        if ($match.Count -eq 1) { return $match[0].FullName }
    }
    for ($i = 0; $i -lt $candidates.Count; $i++) { Write-Host ('{0}. {1}' -f ($i + 1), $candidates[$i].Name) }
    $number = 0
    $answer = Read-Host 'Multiple projects found. Enter the project number'
    if (-not [int]::TryParse($answer, [ref]$number) -or $number -lt 1 -or $number -gt $candidates.Count) { throw 'Invalid project selection.' }
    return $candidates[$number - 1].FullName
}
function Assert-Source([string]$Source) {
    Require-File (Join-Path $Source 'packages\dsh-i18n\src\client\ru\plain-chat.ts')
    foreach ($relative in @('desktop\package.json', 'desktop\src\runtime.cjs', 'shared\tsdown.client.ts', 'shared\web-platform.ts', 'shared\host\dsh-home.ts', 'packages\dsh-web-all\package.json', 'packages\dsh-client-ui-plain-chat\package.json', 'packages\dsh-client-ui-plain-chat\src\index.ts', 'packages\dsh-client-ui-plain-chat\src\client\index.ts', 'packages\dsh-client-ui-plain-chat\tsdown.config.ts', 'packages\dsh-client-ui-plain-chat\cordis.patch.yml', 'packages\dsh-client-ui-plain-chat\presets\workbench-chat\no-tools.mjs')) {
        Require-File (Join-Path $Source $relative)
    }
    if ((Read-Json (Join-Path $Source 'packages\dsh-web-all\package.json')).version -ne $script:Versions.Web) { throw 'Source web version differs from the pinned baseline.' }
    if ((Read-Json (Join-Path $Source 'packages\dsh-client-ui-plain-chat\package.json')).name -ne $script:ChatName) { throw 'Unexpected plain-chat package identity.' }
    $runtimeText = Get-Content -LiteralPath (Join-Path $Source 'desktop\src\runtime.cjs') -Raw
    $mainText = Get-Content -LiteralPath (Join-Path $Source 'desktop\src\main.cjs') -Raw
    if ($runtimeText -notmatch 'DSH_DESKTOP_DEV_ROOT' -or $mainText -notmatch 'resolveDevelopmentRuntime') { throw 'Desktop source is missing the external development runtime integration.' }
}
function Set-LocalEnvironment {
    $script:Node = Join-Path $script:Root 'runtime-node\node.exe'
    $script:Npm = Join-Path $script:Root 'runtime-node\node_modules\npm\bin\npm-cli.js'
    $script:Pnpm = Join-Path $script:Root 'runtime\node_modules\pnpm\bin\pnpm.cjs'
    $script:Dsh = Join-Path $script:Root 'runtime\node_modules\@deepseek-ai\dsh\lib\bin.js'
    $script:Electron = Join-Path $script:Root 'runtime-desktop\node_modules\electron\dist\electron.exe'
    $env:PATH = (Join-Path $script:Root 'runtime-node') + ';' + (Join-Path $script:Root 'runtime\node_modules\.bin') + ';' + $env:PATH
    $env:DSH_HOME = Join-Path $script:Root 'dsh-data'
    $env:DSH_DESKTOP_DEV_ROOT = $script:Root
    $env:DSH_DESKTOP_NODE = $script:Node
    $env:npm_config_cache = Join-Path $script:Root 'runtime\npm-cache'
    $env:npm_config_store_dir = Join-Path $script:Root 'runtime\pnpm-store'
    $env:PNPM_HOME = Join-Path $script:Root 'runtime\pnpm-home'
    $env:XDG_CACHE_HOME = Join-Path $script:Root 'runtime\cache'
    $env:XDG_DATA_HOME = Join-Path $script:Root 'runtime\data'
    $env:electron_config_cache = Join-Path $script:Root 'runtime-desktop\cache'
    foreach ($name in @('ELECTRON_RUN_AS_NODE', 'ELECTRON_OVERRIDE_DIST_PATH', 'ELECTRON_INSTALL_ARCH', 'ELECTRON_INSTALL_PLATFORM', 'DSH_BUILD_FACE', 'NODE_ENV')) {
        Remove-Item -LiteralPath "Env:$name" -ErrorAction SilentlyContinue
    }
}
function Get-Download([string]$Url, [string]$Destination) {
    New-Directory (Split-Path -Parent $Destination)
    $partial = $Destination + '.partial'
    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
    for ($attempt = 1; $attempt -le 3; $attempt++) {
        try {
            Write-Log "Download attempt $attempt : $Url"
            Invoke-WebRequest -UseBasicParsing -Uri $Url -OutFile $partial -TimeoutSec 180
            Move-Item -LiteralPath $partial -Destination $Destination -Force
            return
        } catch { if ($attempt -eq 3) { throw }; Start-Sleep -Seconds 2 }
    }
}
function Assert-Version([string]$Directory, [string]$Package, [string]$Version) {
    $file = Join-Path $Directory ('node_modules\' + $Package.Replace('/', '\') + '\package.json')
    Require-File $file
    if ((Read-Json $file).version -ne $Version) { throw "Version mismatch: $Package (expected $Version)" }
}
function Install-Node {
    $target = Join-Path $script:Root 'runtime-node'
    if ((Test-Path -LiteralPath $script:Node) -and (Test-Path -LiteralPath $script:Npm) -and -not $Repair) {
        $version = & $script:Node --version
        if ($LASTEXITCODE -eq 0 -and $version -eq ('v' + $script:Versions.Node)) { Write-Log 'Reusing local Node.js.'; return }
    }
    $archiveName = 'node-v' + $script:Versions.Node + '-win-x64.zip'
    $cache = Join-Path $script:Root 'runtime\downloads'
    $archive = Join-Path $cache $archiveName
    $sums = Join-Path $cache ('node-v' + $script:Versions.Node + '-SHASUMS256.txt')
    $url = 'https://nodejs.org/dist/v' + $script:Versions.Node + '/'
    Get-Download ($url + 'SHASUMS256.txt') $sums
    $entry = @(Get-Content -LiteralPath $sums | Where-Object { $_ -match ('^[a-fA-F0-9]{64}\s+' + [regex]::Escape($archiveName) + '$') })
    if ($entry.Count -ne 1) { throw 'Official checksum entry missing or ambiguous.' }
    $expected = ($entry[0] -split '\s+')[0]
    if (-not (Test-Path -LiteralPath $archive) -or (Get-FileHash -LiteralPath $archive -Algorithm SHA256).Hash -ne $expected) { Get-Download ($url + $archiveName) $archive }
    if ((Get-FileHash -LiteralPath $archive -Algorithm SHA256).Hash -ne $expected) { throw 'Node.js ZIP SHA256 mismatch; archive was not extracted.' }
    # Keep npm's nested paths below the Windows PowerShell archive path limit.
    $stage = Join-Path $script:Root ('runtime-node-stage-' + [guid]::NewGuid().ToString('N').Substring(0, 8))
    Expand-Archive -LiteralPath $archive -DestinationPath $stage
    $extracted = Join-Path $stage ('node-v' + $script:Versions.Node + '-win-x64')
    Require-File (Join-Path $extracted 'node.exe')
    Require-File (Join-Path $extracted 'node_modules\npm\bin\npm-cli.js')
    if (Test-Path -LiteralPath $target) {
        # Both paths are fixed, resolved children of this workbench; keep the previous runtime intact.
        if ((Get-Item -LiteralPath $target).Attributes -band [IO.FileAttributes]::ReparsePoint) { throw 'runtime-node must be a real directory.' }
        Move-Item -LiteralPath $target -Destination (Join-Path $cache ('previous-node-' + [guid]::NewGuid().ToString('N')))
    }
    Move-Item -LiteralPath $extracted -Destination $target
    Invoke-Tool $script:Node @('--version')
    Invoke-Tool $script:Node @($script:Npm, '--version')
}

# Compressed dependency manifests/locks from the verified local baseline. No user settings or credentials.
$script:BaselineData = ''
function Get-Baseline {
    $bytes = [Convert]::FromBase64String($script:BaselineData)
    $memory = New-Object IO.MemoryStream(,$bytes)
    $gzip = New-Object IO.Compression.GZipStream($memory, [IO.Compression.CompressionMode]::Decompress)
    $reader = New-Object IO.StreamReader($gzip, [Text.Encoding]::UTF8)
    try { return ($reader.ReadToEnd() | ConvertFrom-Json) } finally { $reader.Dispose(); $gzip.Dispose(); $memory.Dispose() }
}
function Install-NpmEnvironment([string]$Name, $Baseline) {
    $directory = Join-Path $script:Root $Name
    $manifestFile = Join-Path $directory 'package.json'
    $lockFile = Join-Path $directory 'package-lock.json'
    $fresh = -not (Test-Path -LiteralPath $manifestFile)
    if ($fresh) { $manifest = $Baseline.manifest } else { $manifest = Read-Json $manifestFile }
    foreach ($section in @('dependencies', 'devDependencies')) {
        if ($Baseline.manifest.$section) {
            $dependencies = Ensure-Object $manifest $section
            foreach ($item in $Baseline.manifest.$section.PSObject.Properties) { Set-Field $dependencies $item.Name $item.Value }
        }
    }
    Write-Json $manifestFile $manifest
    if ($fresh -and -not (Test-Path -LiteralPath $lockFile)) { Write-Text $lockFile $Baseline.lock }
    Backup-File $lockFile
    $verb = 'install'
    if ($Repair -and (Test-Path -LiteralPath $lockFile)) { $verb = 'ci' }
    # npm install reuses a complete tree and its lock; ci is an explicit repair of dependencies only.
    $arguments = @($script:Npm, $verb, '--prefix', $directory, '--include=dev', '--include=optional', '--ignore-scripts=false', '--no-audit', '--no-fund', '--prefer-offline')
    # Build-only SDK packages have incompatible transitive peer ranges in this saved baseline.
    # Keep the recorded dependency tree instead of asking npm to resolve a newer SDK cohort.
    if ($Name -eq 'runtime-dev') { $arguments += '--legacy-peer-deps' }
    Invoke-Tool $script:Node $arguments
    foreach ($section in @('dependencies', 'devDependencies')) {
        if ($Baseline.manifest.$section) {
            foreach ($item in $Baseline.manifest.$section.PSObject.Properties) { Assert-Version $directory $item.Name $item.Value }
        }
    }
}
function Backup-Profile {
    foreach ($relative in @('package.json', 'pnpm-lock.yaml', 'pnpm-workspace.yaml', '.npmrc', 'cordis.patch.yml')) { Backup-File (Join-Path $script:Profile $relative) }
}
function Install-WebProfile($Baseline) {
    Backup-Profile
    $manifestFile = Join-Path $script:Profile 'package.json'
    $fresh = -not (Test-Path -LiteralPath $manifestFile)
    if ($fresh) {
        Write-Json $manifestFile $Baseline.manifest
        Write-Text (Join-Path $script:Profile 'pnpm-lock.yaml') $Baseline.lock
    }
    # Repair an old source link before pnpm resolves dependencies (including after a folder rename).
    $manifest = Read-Json $manifestFile
    if ($manifest.dependencies.$script:ChatName) {
        Set-Field $manifest.dependencies $script:ChatName ('link:../../../' + (Split-Path -Leaf $script:Source) + '/packages/dsh-client-ui-plain-chat')
        Write-Json $manifestFile $manifest
    }
    # Initialize absent auxiliary files through the host's public initializer; it preserves existing files.
    $init = Join-Path $script:Root 'runtime-dev\init-profile.mjs'
    Write-Text $init @'
import { pathToFileURL } from 'node:url';
import path from 'node:path';
const root = process.argv[2];
const boot = await import(pathToFileURL(path.join(root, 'runtime/node_modules/@deepseek-ai/dsh-app-boot/lib/index.js')));
boot.initProfile(path.join(root, 'dsh-data/profiles/web'), boot.PROFILE_TEMPLATES.web.bundles, 'live');
'@
    Invoke-Tool $script:Node @($init, $script:Root)
    # Pass argv directly to Node/pnpm, avoiding the DSH CLI's Windows shell forwarding for local paths.
    $arguments = @($script:Pnpm, 'add', '@linxin666/dsh-web-all@0.3.23', '--save-exact', '--allow-build=cloudflared', '--allow-build=cpu-features', '--allow-build=node-pty', '--allow-build=ssh2')
    if ($Repair -or $script:Moved) { $arguments += '--force' }
    Invoke-Tool $script:Node $arguments $script:Profile
    Register-Bundles
}
function Register-Bundles {
    $file = Join-Path $script:Profile 'package.json'
    $manifest = Read-Json $file
    $dshObject = Ensure-Object $manifest 'dsh'
    $profileObject = Ensure-Object $dshObject 'profile'
    $bundles = @($profileObject.bundles | Where-Object { $null -ne $_ })
    foreach ($bundle in @('@deepseek-ai/dsh-base', '@deepseek-ai/dsh-web-app', '@linxin666/dsh-web-all')) {
        if ($bundles -notcontains $bundle) { $bundles += $bundle }
    }
    foreach ($bundle in @($script:ChatName, '@linxin666/dsh-capabilities')) {
        if ($manifest.dependencies.$bundle -and $bundles -notcontains $bundle) { $bundles += $bundle }
    }
    Set-Field $profileObject 'bundles' $bundles
    if (-not $profileObject.patchReload) { Set-Field $profileObject 'patchReload' 'live' }
    Write-Json $file $manifest
}
function Apply-SharedSettings {
    $settingsScript = Join-Path $script:Source 'scripts\settings-sync.cjs'
    if ((Test-Path -LiteralPath $settingsScript) -and (Test-Path -LiteralPath (Join-Path $script:Root 'shared-settings\manifest.json'))) {
        Invoke-Tool $script:Node @($settingsScript, 'apply', $script:Root)
    }
}
function Build-Workshop {
    Invoke-Tool $script:Node @((Join-Path $script:Source 'scripts\build-workbench.mjs'), $script:Root, $script:Source)
    Backup-Profile
    # Baseline native modules are installed before this step. Runtime snapshots have no lifecycle scripts.
    Invoke-Tool $script:Node @((Join-Path $script:Source 'scripts\install-workbench.mjs'), $script:Root)
    Register-Bundles
}
function Write-Launchers([switch]$MissingOnly) {
    foreach ($entry in @(, @('启动桌面端.cmd', 'Desktop'))) {
        if ($MissingOnly -and (Test-Path -LiteralPath (Join-Path $script:Root $entry[0]))) { continue }
        $content = "@echo off`r`nsetlocal`r`npowershell.exe -NoProfile -ExecutionPolicy Bypass -File `"%~dp0deploy.ps1`" -Mode " + $entry[1] + "`r`nset `"result=%errorlevel%`"`r`nif not `"%result%`"==`"0`" pause`r`nexit /b %result%`r`n"
        Write-Text (Join-Path $script:Root $entry[0]) $content
    }
    # Preserve existing launcher behavior (including stale-lock handling) when filling gaps.
    if ($MissingOnly -and (Test-Path -LiteralPath (Join-Path $script:Root 'start-desktop.ps1'))) { return }
    # Compatibility entry for existing shortcuts; all path discovery now lives in this script.
    Write-Text (Join-Path $script:Root 'start-desktop.ps1') "& powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path `$PSScriptRoot 'deploy.ps1') -Mode Desktop`r`nexit `$LASTEXITCODE`r`n" -Bom
}
function Check-Installation {
    & (Join-Path $script:Root 'external-tools\install.ps1') -Check
    if (-not (Test-Path -LiteralPath $script:Node) -or -not (Test-Path -LiteralPath $script:Npm)) { throw 'Portable Node.js is missing. For an existing workbench run deploy.ps1 -Mode Bootstrap; for a new installation run Deploy.' }
    foreach ($file in @($script:Node, $script:Npm, $script:Pnpm, $script:Dsh, $script:Electron, (Join-Path $script:Profile 'package.json'))) { Require-File $file }
    $version = & $script:Node --version
    if ($LASTEXITCODE -ne 0 -or $version -ne ('v' + $script:Versions.Node)) { throw 'Local Node.js version check failed.' }
    Assert-Version (Join-Path $script:Root 'runtime') '@deepseek-ai/dsh' $script:Versions.Dsh
    Assert-Version (Join-Path $script:Root 'runtime') 'pnpm' $script:Versions.Pnpm
    Assert-Version (Join-Path $script:Root 'runtime-desktop') 'electron' $script:Versions.Electron
    $electronVersionFile = Join-Path $script:Root 'runtime-desktop\node_modules\electron\dist\version'
    Require-File $electronVersionFile
    if (([IO.File]::ReadAllText($electronVersionFile).Trim() -replace '^v', '') -ne $script:Versions.Electron) { throw 'Electron binary version differs from its package version.' }
    Assert-Version $script:Profile '@linxin666/dsh-web-all' $script:Versions.Web
    $manifest = Read-Json (Join-Path $script:Profile 'package.json')
    foreach ($name in @($script:ChatName, '@linxin666/dsh-capabilities', '@linxin666/dsh-web-all')) {
        if (-not ([string]$manifest.dependencies.$name).StartsWith('file:')) { throw "Customized package is not installed: $name. Run Build or Deploy." }
        $installed = Join-Path $script:Profile ('node_modules/' + $name)
        $snapshot = [IO.Path]::GetFullPath((Join-Path $script:Profile $manifest.dependencies.$name.Substring(5)))
        foreach ($relative in @('package.json', 'lib/index.js', 'cordis.patch.yml')) {
            Require-File (Join-Path $installed $relative)
            Require-File (Join-Path $snapshot $relative)
            if ((Get-FileHash -LiteralPath (Join-Path $installed $relative)).Hash -ne (Get-FileHash -LiteralPath (Join-Path $snapshot $relative)).Hash) { throw "Installed package differs from build: $name/$relative" }
        }
    }
    foreach ($bundle in @('@deepseek-ai/dsh-base', '@deepseek-ai/dsh-web-app', '@linxin666/dsh-web-all', $script:ChatName, '@linxin666/dsh-capabilities')) {
        if (@($manifest.dsh.profile.bundles) -notcontains $bundle) { throw "Bundle registration missing: $bundle" }
    }
    foreach ($relative in @('lib\index.js', 'lib\client.js', 'presets\workbench-chat\agent.cordis.yml', 'presets\workbench-chat\preset.yml', 'presets\workbench-chat\no-tools.mjs')) {
        Require-File (Join-Path $script:Profile ('node_modules\' + $script:ChatName.Replace('/', '\') + '\' + $relative))
    }
    foreach ($entry in @('启动桌面端.cmd', '一键部署.cmd')) { Require-File (Join-Path $script:Root $entry) }
    Invoke-Tool $script:Node @($script:Dsh, '--version')
    Invoke-Tool $script:Node @($script:Pnpm, '--version')
    Write-Log 'Installed files, versions, bundle registrations and launchers checked. Model replies require user configuration.'
}
function Install-ExternalTools {
    & (Join-Path $script:Root 'external-tools\install.ps1')
}
function Main {
    if ($Mode -eq 'Tools') { Install-ExternalTools; return }
    if ([Environment]::OSVersion.Platform -ne 'Win32NT' -or [Environment]::OSVersion.Version.Major -lt 10) { throw 'Windows 10/11 or equivalent Windows Server is required.' }
    $arch = $env:PROCESSOR_ARCHITEW6432
    if (-not $arch) { $arch = $env:PROCESSOR_ARCHITECTURE }
    if ($arch -ne 'AMD64') { throw 'This pinned baseline supports Windows x64. ARM64/x86 requires a separately verified dependency baseline.' }
    $script:Source = Select-Source
    Assert-Source $script:Source
    Write-Log "Workbench: $script:Root"
    Write-Log "Source: $script:Source"
    if ($Mode -eq 'Inspect') { Write-Log 'Source and system preflight passed; no files changed.'; return }
    foreach ($directory in @('runtime-node', 'runtime', 'runtime-desktop', 'runtime-dev', 'dsh-data')) {
        $path = Join-Path $script:Root $directory
        if ((Test-Path -LiteralPath $path) -and ((Get-Item -LiteralPath $path).Attributes -band [IO.FileAttributes]::ReparsePoint)) {
            throw "Environment root must be a real workbench directory, not a junction/symlink: $path"
        }
    }
    Set-LocalEnvironment
    $script:Profile = Join-Path $env:DSH_HOME 'profiles\web'
    if ($Mode -eq 'Check') { Check-Installation; return }
    if ($Mode -eq 'Desktop') {
        foreach ($file in @($script:Node, $script:Dsh, (Join-Path $script:Profile 'package.json'), $script:Electron)) { Require-File $file }
        Apply-SharedSettings
        $app = Join-Path $script:Source 'desktop'
        Start-Process -FilePath $script:Electron -ArgumentList ('"' + $app + '"') -WorkingDirectory $script:Root -WindowStyle Normal | Out-Null
        return
    }
    $dev = Join-Path $script:Root 'runtime-dev'
    New-Directory $dev
    $lock = $null
    try {
        try { $lock = [IO.File]::Open((Join-Path $dev 'deploy.lock'), 'OpenOrCreate', 'ReadWrite', 'None') } catch { throw 'Another deployment/build is running, or runtime-dev is not writable.' }
        $runId = (Get-Date -Format 'yyyyMMdd-HHmmss') + '-' + [guid]::NewGuid().ToString('N').Substring(0, 8)
        New-Directory (Join-Path $dev 'logs')
        $script:Log = Join-Path $dev ('logs\deploy-' + $runId + '.log')
        $script:BackupRoot = Join-Path $dev ('backups\deploy-' + $runId)
        $selectionFile = Join-Path $dev 'deployment-selection.json'
        $script:Moved = $false
        if (Test-Path -LiteralPath $selectionFile) { $script:Moved = (Read-Json $selectionFile).lastRoot -ne $script:Root }
        if ($Mode -eq 'Bootstrap') {
            # Fill portable runtime gaps without reinstalling dependencies or touching the profile.
            $script:Step = 'Node.js'; Install-Node
            $script:Step = 'Missing launchers'; Write-Launchers -MissingOnly
            $script:Step = 'Validation'; Check-Installation
            Write-Log 'Portable Node and missing launchers prepared; existing dependencies and profile retained.'
            return
        }
        if ($Mode -eq 'Deploy') {
            $script:Step = 'External tools'; Install-ExternalTools
            $script:Step = 'Node.js'; Install-Node
            $baseline = Get-Baseline
            $script:Step = 'DSH and pnpm'; Install-NpmEnvironment 'runtime' $baseline.runtime
            $script:Step = 'Electron'; Install-NpmEnvironment 'runtime-desktop' $baseline.desktop
            Invoke-Tool $script:Node @((Join-Path $script:Root 'runtime-desktop\node_modules\electron\install.js'))
            Require-File $script:Electron
            Invoke-Tool $script:Electron @('--version')
            $script:Step = 'Development dependencies'; Install-NpmEnvironment 'runtime-dev' $baseline.dev
            $script:Step = 'Web profile'; Install-WebProfile $baseline.web
        } else {
            foreach ($file in @($script:Node, $script:Pnpm, (Join-Path $script:Profile 'package.json'), (Join-Path $dev 'node_modules\tsdown\dist\run.mjs'))) { Require-File $file }
        }
        $script:Step = 'Local Workshop build and registration'; Build-Workshop
        $script:Step = 'Shared settings'; Apply-SharedSettings
        $script:Step = 'Launchers'; Write-Launchers
        $script:Step = 'Validation'; Check-Installation
        Write-Json $selectionFile ([pscustomobject]@{ sourceName = Split-Path -Leaf $script:Source; lastRoot = $script:Root; completedAt = (Get-Date -Format o) })
        Write-Log 'Completed. Launch Desktop. Restart an already running host to load the rebuilt plugin.'
        Write-Log "Log: $script:Log"
    } finally { if ($lock) { $lock.Dispose() } }
}

# Dot-sourcing loads functions for offline regression tests without deploying anything.
if ($MyInvocation.InvocationName -ne '.') {
    try { Main } catch {
        Write-Log ('FAILED: ' + $_.Exception.Message)
        Write-Host 'Fix the reported step and run again. Existing data is retained. Native build failures may require Python / Microsoft C++ Build Tools; this script does not install system components.' -ForegroundColor Yellow
        if ($script:Log) { Write-Host "Log: $script:Log" }
        exit 1
    }
}
